import React from 'react'
import { useRandomPokemon } from '../context/RandomPokemonContext'

function RandomPokemonRerollButton() {
  const { rerollPokemon } = useRandomPokemon()

  // Trigger reroll without reloading
  const handleReroll = () => {
    const totalPokemons = 151 // Replace with actual Pokémon count if known
    rerollPokemon(totalPokemons)
  }

  return (
    <div className='p-8 text-center'>
      <button
        onClick={handleReroll}
        className='px-4 py-2 bg-blue-light text-white rounded-lg hover:bg-blue-dark'
      >
        Reroll Pokémon
      </button>
    </div>
  )
}

export default RandomPokemonRerollButton
